    public static AnalyzerHelp Get(Type analyzerType, string fallbackDescription)
    {
        if (Entries.TryGetValue(analyzerType, out var help))
        {
            return help;
        }

        return new AnalyzerHelp(
            fallbackDescription,
            string.Empty,
            string.Empty,
            string.Empty,
            "Подробная справка для этого анализатора пока не заполнена.");
    }
}
